mapper.update:
update application

    status = #{status},
    interview_time = #{interviewTime},
    remark = #{remark},
    update_time = #{updateTime}

where id = #{id}

mapper.select:
select a.id, a.user_id, u.name userName, a.job_id, j.title jobTitle, j.company_id, c.name companyName, a.resume_id, r.name resumeName, a.status, a.interview_time interviewTime, a.remark, a.create_time createTime from application a join user u on a.user_id = u.id join job j on a.job_id = j.id join company c on j.company_id = c.id join resume r on a.resume_id = r.id
and a.job_id = #{jobId} and a.status = #{status}
order by a.create_time desc
